create temporary table security_results(name text,passed boolean);
create temporary table security_ids(name text primary key,id uuid);
grant select,insert on security_results,security_ids to authenticated;
insert into security_ids values('manager_a','10000000-0000-0000-0000-000000000001'),('employee_a','10000000-0000-0000-0000-000000000002');
insert into auth.users(id,email,raw_user_meta_data) values('20000000-0000-0000-0000-000000000001','manager-b@example.invalid','{"role":"manager","workspace_id":"fake"}'),('20000000-0000-0000-0000-000000000002','employee-b@example.invalid','{}'),('30000000-0000-0000-0000-000000000001','outsider@example.invalid','{}');
insert into security_ids values('manager_b','20000000-0000-0000-0000-000000000001'),('employee_b','20000000-0000-0000-0000-000000000002'),('outsider','30000000-0000-0000-0000-000000000001');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
select set_config('request.jwt.claim.aal','aal1',false);
insert into security_results values('Manager without MFA cannot use privileged access',not private.is_manager());
do $$declare blocked boolean:=false;begin begin perform public.create_company_invitation();exception when others then blocked:=true;end;insert into security_results values('Manager invitation requires MFA',blocked);end $$;
select set_config('request.jwt.claim.aal','aal2',false);
insert into security_results values('Manager with MFA has company access',private.is_manager());
insert into security_results values('Cloud AI off by default',(public.workspace_context()->>'cloud_ai_allowed')::boolean=false);
insert into security_results values('Existing encrypted key preserved',public.provider_configuration('server-test')->>'encrypted_key'='old-encrypted-value');
select public.configure_company(true,'Company A');
insert into security_results values('Company manager can allow cloud AI',(public.workspace_context()->>'cloud_ai_allowed')::boolean);
do $$declare path text;d public.documents;r jsonb;input jsonb;blocked boolean;begin
 input:='{"supplier":"Private Supplier","invoice_number":"CONF-001","invoice_date":"2026-10-01","due_date":"2026-11-01","currency":"INR","category":"Other","items":[{"description":"Paper","quantity":3,"unit_price":0.1}],"tax":0.2,"total":0.5,"notes":"","uncertainties":[]}';
 path:=auth.uid()::text||'/original.pdf';insert into storage.objects(bucket_id,name) values('invoice-documents',path);
 blocked:=false;begin perform public.register_document(path,'original.pdf','application/pdf',100);exception when others then blocked:=true;end;insert into security_results values('Old browser registration disabled',blocked);
 blocked:=false;begin perform public.register_validated_document(path,'original.pdf','application/pdf',100,'bad');exception when others then blocked:=true;end;insert into security_results values('Validated upload requires server authorization',blocked);
 d:=public.register_validated_document(path,'original.pdf','application/pdf',100,'server-test');insert into security_ids values('document_a',d.id);insert into security_results values('PDF registration has company boundary',d.workspace_id=private.current_workspace());
 d:=public.start_document_read(d.id,'server-test',false);d:=public.finish_document_read(d.id,d.run_id,'server-test',input,'Source total 0.50',repeat('d',64),'local-text','');r:=public.commit_document(d.id,'server-test');insert into security_ids values('invoice_a',(r->>'invoice_id')::uuid);
 insert into security_results values('Database calculates decimal amounts exactly',(select checks->>'passed'='true' and (checks->>'expected_total')::numeric=0.5 from public.invoices where id=(r->>'invoice_id')::uuid));
 perform public.record_document_access(d.id);insert into security_results values('Original access recorded',exists(select 1 from public.security_events where event='original_opened' and details->>'document_id'=d.id::text));
 r:=public.review_document(d.id,0,jsonb_set(input,'{total}','0.51'),'Verified wrong total against original','approve');insert into security_results values('One paise mismatch blocks approval',r->>'state'='needs_correction');
 r:=public.review_document(d.id,1,input,'Corrected extraction against original','approve');insert into security_results values('Same MFA manager can correct and approve',r->>'state'='approved');
 insert into security_results values('First extraction unchanged after correction',(select extracted->>'total'='0.5' from public.documents where id=d.id));
 insert into security_results values('Correction history preserved',(select count(*)>=2 from public.document_audit where document_id=d.id));
 blocked:=false;begin delete from storage.objects where name=path;blocked:=not found;exception when others then blocked:=true;end;insert into security_results values('Registered original cannot be deleted',blocked);
 end $$;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select public.ensure_profile();
insert into security_results values('User metadata cannot grant company membership',private.current_workspace() is null);
insert into security_results values('Unassigned user sees no invoices',(select count(*)=0 from public.invoices));
select public.create_company('Company B');
insert into security_results values('New company has isolated provider',not(public.provider_configuration('server-test')?'encrypted_key'));
insert into security_results values('Other company manager sees no invoices',(select count(*)=0 from public.invoices));
insert into security_results values('Other company manager sees no documents',(select count(*)=0 from public.documents));
insert into security_results values('Other company manager sees no history',(select count(*)=0 from public.document_audit));
insert into security_results values('Other company manager sees no activity',(select count(*)=0 from public.activity));
insert into security_results values('Other company chatbot search finds no invoices',(public.search_invoices('Private Supplier')->>'total')::int=0);
insert into security_results values('Other company cannot read storage object',(select count(*)=0 from storage.objects));
do $$declare blocked boolean;doc uuid;inv uuid;code text;input jsonb;d public.documents;r jsonb;path text;begin
 select id into doc from security_ids where name='document_a';select id into inv from security_ids where name='invoice_a';
 blocked:=false;begin perform public.assess_invoice(inv);exception when others then blocked:=true;end;insert into security_results values('Cross-company assessment denied',blocked);
 blocked:=false;begin perform public.decide_invoice(inv,'rejected','Trying to reject other company');exception when others then blocked:=true;end;insert into security_results values('Cross-company decision denied',blocked);
 blocked:=false;begin perform public.review_document(doc,0,null,'Cross company reject','reject');exception when others then blocked:=true;end;insert into security_results values('Cross-company correction denied',blocked);
 blocked:=false;begin perform public.start_document_read(doc,'server-test',false);exception when others then blocked:=true;end;insert into security_results values('Cross-company read RPC denied',blocked);
 blocked:=false;begin perform public.start_review(inv);exception when others then blocked:=true;end;insert into security_results values('Cross-company review RPC denied',blocked);
 blocked:=false;begin perform public.record_document_access(doc);exception when others then blocked:=true;end;insert into security_results values('Cross-company original access denied',blocked);
 blocked:=false;begin perform public.promote_member('10000000-0000-0000-0000-000000000002');exception when others then blocked:=true;end;insert into security_results values('Cross-company promotion denied',blocked);
 input:='{"supplier":"Private Supplier","invoice_number":"CONF-001","invoice_date":"2026-10-01","due_date":"2026-11-01","currency":"INR","category":"Other","items":[{"description":"Paper","quantity":3,"unit_price":0.1}],"tax":0.2,"total":0.5,"notes":"","uncertainties":[]}';
 path:=auth.uid()::text||'/original.jpg';insert into storage.objects(bucket_id,name) values('invoice-documents',path);d:=public.register_validated_document(path,'original.jpg','image/jpeg',100,'server-test');d:=public.start_document_read(d.id,'server-test',false);d:=public.finish_document_read(d.id,d.run_id,'server-test',input,'Different company original',repeat('d',64),'local-text','');r:=public.commit_document(d.id,'server-test');
 insert into security_results values('Same number and hash in another company cause no leak or false duplicate',r->>'invoice_id' is not null and not (public.assess_invoice((r->>'invoice_id')::uuid)->>'blocked')::boolean);
 code:=public.create_company_invitation();perform set_config('test.invitation',code,false);
 end $$;
